def unique_names(values):
    if not isinstance(values, list):
        raise TypeError("unique_names requires a list of strings")
    seen = set()
    result = []
    for value in values:
        stripped = value.strip()
        if not stripped:
            continue
        lowercased = stripped.casefold()
        if lowercased in seen:
            continue
        seen.add(lowercased)
        result.append(stripped)
    return result
